import{_ as s,c as t,o as n,j as e,a as l}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"巽下離上 鼎：","description":"京氏易傳 - 巽下離上 鼎：","frontmatter":{"title":"巽下離上 鼎：","description":"京氏易傳 - 巽下離上 鼎："},"headers":[],"relativePath":"classics/jingshi/052.md","filePath":"classics/jingshi/052.md"}'),i={name:"classics/jingshi/052.md"};function r(c,a,o,p,d,m){return n(),t("div",null,[...a[0]||(a[0]=[e("h1",{id:"巽下離上-鼎",tabindex:"-1"},[l("巽下離上 鼎： "),e("a",{class:"header-anchor",href:"#巽下離上-鼎","aria-label":"Permalink to “巽下離上 鼎：”"},"​")],-1),e("p",null,"木能巽火，故鼎之象。亨飪見新，供祭明矣。《易》曰：“鼎取新”。（虎易注：此句出於雜卦傳，原句為“鼎，取新也”。）【木見火中，發火木相資，象鼎之兆。下穴為足，中虛見納，飪熟之義明矣。凡飪熟，享祀為先。故曰供祭明矣。變生也。】陰陽得應，居中履順，三公之義，繼於君也。【九三成鼎之德，六五委任得賢臣，假之位，以斯明矣。】陰穴見火，順於上也；中虛見納，受辛於內也。金玉之鉉在乎陽，饗新亨飪在乎陰。與巽為飛伏。【辛亥水，己丑土。】九二立大夫為世，六五居尊見應。",-1),e("p",null,"建始庚戌至乙卯【寒露，春分。】積算起乙卯至甲寅，週而復始。分土木入離巽。【分土木二象入離巽，配鼎卦。】",-1),e("p",null,"五星從位起鎮星，【土星入火宮。】奎宿從位降辛亥水，【二十八宿，分奎宿入鼎卦九二辛亥位上。】分氣候三十六。【起宮數三十六宮配卦算吉凶。】",-1),e("p",null,"火居木上，二氣交合，陰陽巽順，器具形成。金玉堅剛，配象陰陽，升降六位，遞相遷次，",-1),e("p",null,"九三適變，以陽入陰，見乎坎險。【鼎九三爻之義，陰成坎卦，外象，內坎外離，二氣不交，見未濟卦。】降入水火未濟卦。（虎易注：水火未濟，當為火水未濟之誤。）",-1)])])}const f=s(i,[["render",r]]);export{_ as __pageData,f as default};
